Export exactly `{ createSignalHub }`. A hub exposes `on(name, listener)`, `off(name, listener)`, `emit(name, value)`, and `listenerCount(name)`. Names must be non-empty strings and listeners must be functions. Duplicate registrations are allowed. `off` removes only the first matching registration and returns whether one was removed.

`emit` calls listeners in registration order and returns their result values in that order. Its listener sequence must be snapshotted at the start: additions and removals made by a listener affect later emissions only. An empty signal returns `[]`. Listener exceptions propagate immediately. The hub retains listener function identities but must not expose or accept aliases to its internal listener arrays.

Known-bad source:
```javascript
'use strict';

function createSignalHub() {
  const signals = new Map();

  function validName(name) {
    if (typeof name !== 'string' || name.length === 0) throw new TypeError('name must be non-empty');
  }

  return {
    on(name, listener) {
      validName(name);
      if (typeof listener !== 'function') throw new TypeError('listener must be a function');
      const listeners = signals.get(name) || [];
      listeners.push(listener);
      signals.set(name, listeners);
    },
    off(name, listener) {
      validName(name);
      if (typeof listener !== 'function') throw new TypeError('listener must be a function');
      const listeners = signals.get(name);
      if (!listeners) return false;
      const index = listeners.indexOf(listener);
      if (index < 0) return false;
      listeners.splice(index, 1);
      if (listeners.length === 0) signals.delete(name);
      return true;
    },
    emit(name, value) {
      validName(name);
      const listeners = signals.get(name) || [];
      return listeners.map(listener => listener(value));
    },
    listenerCount(name) {
      validName(name);
      return (signals.get(name) || []).length;
    }
  };
}

module.exports = { createSignalHub };
```

