'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['createSignalHub']);
const { createSignalHub } = api;

const hub = createSignalHub();
assert.deepStrictEqual(hub.emit('empty', 1), []);
assert.strictEqual(hub.listenerCount('empty'), 0);
assert.throws(() => hub.on('', () => {}), TypeError);
assert.throws(() => hub.off(1, () => {}), TypeError);
assert.throws(() => hub.emit('', 1), TypeError);
assert.throws(() => hub.listenerCount(null), TypeError);
assert.throws(() => hub.on('x', null), TypeError);
assert.throws(() => hub.off('x', null), TypeError);

const calls = [];
function repeated(value) { calls.push('r:' + value); return 'R'; }
function middle(value) { calls.push('m:' + value); return 'M'; }
hub.on('sig', repeated);
hub.on('sig', middle);
hub.on('sig', repeated);
assert.strictEqual(hub.listenerCount('sig'), 3);
assert.strictEqual(hub.off('sig', repeated), true);
assert.strictEqual(hub.listenerCount('sig'), 2);
assert.deepStrictEqual(hub.emit('sig', 5), ['M', 'R']);
assert.deepStrictEqual(calls, ['m:5', 'r:5']);
assert.strictEqual(hub.off('sig', function other() {}), false);

const snapshotHub = createSignalHub();
const order = [];
function late(value) { order.push('late:' + value); return 'late'; }
function secondListener(value) { order.push('second:' + value); return 'second'; }
function firstListener(value) {
  order.push('first:' + value);
  snapshotHub.off('event', secondListener);
  snapshotHub.on('event', late);
  return 'first';
}
snapshotHub.on('event', firstListener);
snapshotHub.on('event', secondListener);
assert.deepStrictEqual(snapshotHub.emit('event', 'A'), ['first', 'second']);
assert.deepStrictEqual(order, ['first:A', 'second:A']);
order.length = 0;
assert.deepStrictEqual(snapshotHub.emit('event', 'B'), ['first', 'late']);
assert.deepStrictEqual(order, ['first:B', 'late:B']);

const throwing = createSignalHub();
const reached = [];
throwing.on('x', () => { reached.push(1); return 1; });
throwing.on('x', () => { reached.push(2); throw new Error('boom'); });
throwing.on('x', () => { reached.push(3); });
assert.throws(() => throwing.emit('x', 0), /boom/);
assert.deepStrictEqual(reached, [1, 2]);

